import XCTest
@testable import FloeMusicCore
#if canImport(AudioToolbox)
import AudioToolbox
#endif

final class MIDIFileExchangeTests: XCTestCase {
    /// Hand-authored SMF, not generated by the interchange writer under test.
    private func fixture() -> Data {
        let conductor: [UInt8] = [0,0xFF,0x51,3,7,0xA1,0x20, 0,0xFF,0x58,4,3,3,24,8, 0x83,0x60,0xFF,0x51,3,0x0F,0x42,0x40, 0,0xFF,0x2F,0]
        let notes: [UInt8] = [0,0xFF,3,4,76,101,97,100, 0,0xC2,40, 0,0xB2,64,127, 0,0xE2,0,80,
                              0,0x92,60,100, 0x81,0x70,60,0, 0,0xB2,64,0, 0,0xFF,1,3,120,121,122, 0,0xFF,0x2F,0]
        var data = Data([77,84,104,100,0,0,0,6,0,1,0,2,1,0xE0])
        for body in [conductor, notes] { data.append(contentsOf: [77,84,114,107,0,0,0,UInt8(body.count)] + body) }
        return data
    }
    func testRealSMFImportsNameChannelProgramsControllersAndMeterMap() throws {
        let result = try MusicMIDIFileExchange.read(fixture())
        XCTAssertEqual(result.tempoMap.ticksPerQuarter, 480)
        XCTAssertEqual(result.tempoMap.segments.map(\.beatsPerBar), [3,3])
        XCTAssertEqual(result.tempoMap.segments.map(\.beatUnit), [8,8])
        XCTAssertEqual(result.tempoMap.segments.map(\.bpm), [120,60])
        XCTAssertEqual(result.tracks.first?.name, "Lead")
        guard case .midi(let payload) = try XCTUnwrap(result.tracks.first?.clips.first).body else { return XCTFail("MIDI") }
        XCTAssertEqual(payload.notes.first?.durationTicks, 240)
        XCTAssertEqual(payload.notes.first?.channel, 2)
        XCTAssertEqual(payload.programChanges.first?.program, 40)
        XCTAssertEqual(payload.programChanges.first?.channel, 2)
        XCTAssertEqual(payload.controllerPoints.filter { $0.controller == 64 }.map(\.value), [127,0])
        XCTAssertEqual(payload.controllerPoints.first { $0.controller == 128 }?.value, 10_240)
        XCTAssertEqual(result.originalOnlyEventCount, 1)
        let rescaled = try MusicMIDIFileExchange.read(fixture(), ticksPerQuarter: 960)
        guard case .midi(let scaled) = try XCTUnwrap(rescaled.tracks.first?.clips.first).body else { return XCTFail("MIDI") }
        XCTAssertEqual(scaled.notes.first?.durationTicks, 480)
        XCTAssertEqual(rescaled.tempoMap.segments.last?.startTick.value, 960)
    }
    func testEditedDocumentExportsStandardMIDIWithActualOffsetsAndExpressions() throws {
        let imported = try MusicMIDIFileExchange.read(fixture())
        var track = try XCTUnwrap(imported.tracks.first)
        track.clips[0].offset = try imported.tempoMap.sample(atTick: .init(960))
        var document = try MusicDocument(name: "exchange", tempoMap: imported.tempoMap, tracks: [track])
        guard case .midi(var payload) = document.tracks[0].clips[0].body else { return XCTFail("MIDI") }
        payload.notes[0].pitch = 67; payload.notes[0].velocity = 87
        document.tracks[0].clips[0].body = .midi(payload)
        let data = try MusicMIDIFileExchange.write(document)
        #if canImport(AudioToolbox)
        var sequence: MusicSequence?
        XCTAssertEqual(NewMusicSequence(&sequence), noErr)
        let actual = try XCTUnwrap(sequence); defer { DisposeMusicSequence(actual) }
        XCTAssertEqual(MusicSequenceFileLoadData(actual, data as CFData, .midiType, []), noErr)
        var count: UInt32 = 0
        XCTAssertEqual(MusicSequenceGetTrackCount(actual, &count), noErr)
        XCTAssertGreaterThan(count, 0)
        #endif
        let decoded = try MusicMIDIFileExchange.read(data)
        guard case .midi(let exported) = try XCTUnwrap(decoded.tracks.first?.clips.first).body else { return XCTFail("MIDI") }
        XCTAssertEqual(exported.notes.first?.pitch, 67)
        XCTAssertEqual(exported.notes.first?.velocity, 87)
        XCTAssertEqual(exported.notes.first?.startTick.value, 960)
        XCTAssertEqual(exported.programChanges.first?.tick.value, 960)
        XCTAssertEqual(exported.programChanges.first?.program, 40)
        XCTAssertEqual(exported.controllerPoints.first { $0.controller == 128 }?.value, 10_240)
        XCTAssertEqual(decoded.tempoMap, imported.tempoMap)
    }
    func testMalformedUnsupportedAndTruncatedMIDIRejectWithoutChangingInput() throws {
        let original = fixture()
        var smpte = original; smpte[12] = 0xE7
        var type2 = original; type2[9] = 2
        for bytes in [Data(), original.prefix(10), original.dropLast(), smpte, type2] {
            XCTAssertThrowsError(try MusicMIDIFileExchange.read(Data(bytes)))
        }
        XCTAssertEqual(original, fixture())
    }
    func testLegacyChannelZeroAndProgramsSurviveSplitAndJSON() throws {
        let legacy = Data("{\"controller\":64,\"tick\":{\"value\":0},\"value\":127}".utf8)
        XCTAssertEqual(try JSONDecoder().decode(MusicMIDIControllerPoint.self, from: legacy).channel, 0)
        let trackID = MusicTrackID()
        let payload = try MusicMIDIClipPayload(durationTicks: 1920, notes: [], controllerPoints: [
            .init(controller: 64, tick: .init(0), value: 127, channel: 2),
            .init(controller: 64, tick: .init(0), value: 0, channel: 3)
        ], programChanges: [.init(tick: .init(0), channel: 2, program: 40)])
        let clip = try MusicClip(name: "expressions", trackID: trackID, offset: .init(0), body: .midi(payload))
        let map = try MusicFixtures.defaultTempoMap()
        let split = try MusicWorkbenchEditing.split(clip, at: map.sample(atTick: .init(960)), tempoMap: map)
        guard case .insertClip(let right) = split.last, case .midi(let rightPayload) = right.body else { return XCTFail("split") }
        XCTAssertEqual(rightPayload.controllerPoints.map(\.channel), [2,3])
        XCTAssertEqual(rightPayload.programChanges.first?.tick.value, 0)
        XCTAssertEqual(try JSONDecoder().decode(MusicMIDIClipPayload.self, from: JSONEncoder().encode(rightPayload)), rightPayload)
    }
    func testMeterRulerKeepsTempoOnlyChangesAndUsesActualBeatUnit() throws {
        let map = try MusicTempoMap(segments: [
            .init(startTick: .init(0), bpm: 120, beatsPerBar: 3, beatUnit: 8),
            .init(startTick: .init(480), bpm: 60, beatsPerBar: 3, beatUnit: 8),
            .init(startTick: .init(1920), bpm: 90, beatsPerBar: 6, beatUnit: 8)
        ])
        let marks = MusicMusicalRuler.marks(tempoMap: map, through: 3360)
        XCTAssertEqual(marks.prefix(4).map(\.tick), [0,480,960,1440])
        XCTAssertEqual(marks.first { $0.tick == 1440 }?.bar, 2)
        XCTAssertEqual(marks.first { $0.tick == 1920 }?.beat, 1)
        XCTAssertEqual(marks.first { $0.tick == 1920 }?.bar, 3)
        XCTAssertEqual(try map.sample(atTick: .init(960)).value, 36_000)
    }
    func testAgentExpressionEditUsesSameClipAndRetainsNotes() throws {
        let imported = try MusicMIDIFileExchange.read(fixture())
        let document = try MusicDocument(name: "AI same original", tempoMap: imported.tempoMap, tracks: imported.tracks)
        let original = try XCTUnwrap(document.tracks.first?.clips.first)
        let data = Data("[{\"op\":\"midi.clip.update\",\"clipID\":\"\(original.id.rawValue)\",\"controllerPointsMode\":\"merge\",\"controllerPoints\":[{\"controller\":64,\"channel\":3,\"tick\":0,\"value\":127}],\"programChangesMode\":\"merge\",\"programChanges\":[{\"channel\":3,\"tick\":0,\"program\":12}]}]".utf8)
        let operations = try MusicEditJSONCodec.decode(String(decoding: data, as: UTF8.self), document: document)
        guard case .updateClip(let edited) = operations.first, case .midi(let payload) = edited.body,
              case .midi(let previous) = original.body else { return XCTFail("AI edit") }
        XCTAssertEqual(edited.id, original.id)
        XCTAssertEqual(payload.notes, previous.notes)
        XCTAssertEqual(payload.controllerPoints.count, previous.controllerPoints.count + 1)
        XCTAssertEqual(payload.programChanges.map(\.channel), [2,3])
    }
}
